package com.andye.warmod.radar.display.client;import com.andye.warmod.block.RadarDisplayPanelBlock;import com.andye.warmod.block.entity.RadarDisplayPanelBlockEntity;import com.andye.warmod.radar.station.RadarSweepMath;import com.andye.warmod.warhead.client.render.WarheadRenderPipelines;import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.client.renderer.feature.ModelFeatureRenderer;import net.minecraft.client.renderer.state.level.CameraRenderState;import net.minecraft.world.phys.Vec3;import org.jspecify.annotations.Nullable;
public final class RadarDisplayBlockEntityRenderer implements BlockEntityRenderer<RadarDisplayPanelBlockEntity,RadarDisplayRenderState>{public RadarDisplayBlockEntityRenderer(BlockEntityRendererProvider.Context c){}@Override public RadarDisplayRenderState createRenderState(){return new RadarDisplayRenderState();}@Override public void extractRenderState(RadarDisplayPanelBlockEntity be,RadarDisplayRenderState s,float partial,Vec3 camera,ModelFeatureRenderer.@Nullable CrumblingOverlay overlay){BlockEntityRenderer.super.extractRenderState(be,s,partial,camera,overlay);s.size=be.size();s.controller=be.controllerPanel();s.online=be.link()!=null&&be.valid();s.facing=be.getBlockState().getValue(RadarDisplayPanelBlock.FACING);long time=be.getLevel()==null?0:be.getLevel().getGameTime();s.sweep=RadarSweepMath.angleAt(time,partial,be.link()==null?0:be.link().radarId().getLeastSignificantBits());}@Override public void submit(RadarDisplayRenderState s,PoseStack pose,SubmitNodeCollector collector,CameraRenderState camera){if(!s.controller||s.size<1)return;pose.pushPose();switch(s.facing){case SOUTH->pose.mulPose(new org.joml.Quaternionf().rotateY((float)Math.PI));case EAST->pose.mulPose(new org.joml.Quaternionf().rotateY((float)-Math.PI/2));case WEST->pose.mulPose(new org.joml.Quaternionf().rotateY((float)Math.PI/2));default->{}}collector.submitCustomGeometry(pose,WarheadRenderPipelines.NUCLEAR_FLASH,(p,b)->RadarDisplayPrimitiveBuilder.render(p,b,s.size,s.facing,s.online,s.sweep));pose.popPose();}@Override public int getViewDistance(){return 256;}@Override public boolean shouldRenderOffScreen(){return true;}}
